-- درسان إضافيان لكل من العوالم الأربعة الجديدة (2026-11-25)

INSERT INTO lessons (subject_id, slug, title_ar, description_ar, content_ar, age_group, difficulty, duration_min, points, sort_order)
SELECT s.id, v.slug, v.title, v.descr, v.content, v.age, v.diff, 5, v.pts, v.ord
FROM subjects s
JOIN (VALUES
  ('languages', 'greetings-in-english', 'التحية بالإنجليزية', 'كلمات نقولها كل يوم بالإنجليزية',
   '<h2>التحية بالإنجليزية</h2><p>مرحبًا = <b dir="ltr">Hello</b> (هَلُو)</p><p>صباح الخير = <b dir="ltr">Good morning</b> (جُود مُورْنِنج)</p><p>شكرًا = <b dir="ltr">Thank you</b> (ثَانْك يُو)</p><p>مع السلامة = <b dir="ltr">Goodbye</b> (جُود بَاي)</p><p>جرّب أن تقول Good morning لأهلك غدًا صباحًا!</p>',
   '6-8', 1, 10, 2),
  ('languages', 'numbers-in-english', 'الأعداد بالإنجليزية', 'نعدّ من واحد إلى خمسة بالإنجليزية',
   '<h2>الأعداد بالإنجليزية</h2><p>١ = <b dir="ltr">One</b> (وَان)</p><p>٢ = <b dir="ltr">Two</b> (تُو)</p><p>٣ = <b dir="ltr">Three</b> (ثْرِي)</p><p>٤ = <b dir="ltr">Four</b> (فُور)</p><p>٥ = <b dir="ltr">Five</b> (فَايْف)</p><p>عُدّ أصابع يدك بالإنجليزية: One, Two, Three, Four, Five!</p>',
   '6-8', 1, 10, 3),
  ('thinking', 'odd-one-out', 'مَنِ الْمُخْتَلِفُ؟', 'نَبْحَثُ عَنِ الشَّيْءِ الَّذِي لَا يُشْبِهُ الْبَقِيَّةَ',
   '<h2>مَنِ الْمُخْتَلِفُ؟</h2><p>انْظُرْ إِلَى الْأَشْيَاءِ، وَابْحَثْ عَنِ الَّذِي لَا يُشْبِهُهَا.</p><p>🍎 🍌 🍇 🚗 : السَّيَّارَةُ مُخْتَلِفَةٌ، لِأَنَّهَا لَيْسَتْ فَاكِهَةً.</p><p>🐶 🐱 🐰 ✏️ : الْقَلَمُ مُخْتَلِفٌ، لِأَنَّهُ لَيْسَ حَيَوَانًا.</p><p>اسْأَلْ نَفْسَكَ: مَا الشَّيْءُ الْمُشْتَرَكُ بَيْنَهَا؟</p>',
   '3-5', 1, 10, 2),
  ('thinking', 'big-and-small', 'كَبِيرٌ وَصَغِيرٌ', 'نُقَارِنُ الْأَشْيَاءَ وَنُرَتِّبُهَا',
   '<h2>كَبِيرٌ وَصَغِيرٌ</h2><p>الْفِيلُ 🐘 كَبِيرٌ، وَالْقِطَّةُ 🐱 أَصْغَرُ مِنْهُ، وَالنَّمْلَةُ 🐜 أَصْغَرُ مِنْهُمَا.</p><p>نُرَتِّبُ مِنَ الصَّغِيرِ إِلَى الْكَبِيرِ: النَّمْلَةُ، ثُمَّ الْقِطَّةُ، ثُمَّ الْفِيلُ.</p><p>انْظُرْ حَوْلَكَ: أَيُّ شَيْءٍ فِي غُرْفَتِكَ هُوَ الْأَكْبَرُ؟</p>',
   '3-5', 1, 10, 3),
  ('creativity', 'shapes-around-us', 'الْأَشْكَالُ حَوْلَنَا', 'نَتَعَرَّفُ عَلَى الدَّائِرَةِ وَالْمُرَبَّعِ وَالْمُثَلَّثِ',
   '<h2>الْأَشْكَالُ حَوْلَنَا</h2><p>⚪ الدَّائِرَةُ: مُسْتَدِيرَةٌ مِثْلُ الشَّمْسِ وَالْكُرَةِ.</p><p>⬜ الْمُرَبَّعُ: لَهُ أَرْبَعَةُ أَضْلَاعٍ مُتَسَاوِيَةٍ.</p><p>🔺 الْمُثَلَّثُ: لَهُ ثَلَاثَةُ أَضْلَاعٍ، مِثْلُ قِطْعَةِ الْبِيتْزَا.</p><p>ارْسُمْ بَيْتًا مِنْ مُرَبَّعٍ وَمُثَلَّثٍ فِي «ارْسُمْ»!</p>',
   '3-5', 1, 10, 2),
  ('creativity', 'warm-and-cool-colors', 'ألوان دافئة وألوان باردة', 'كيف تجعلنا الألوان نشعر؟',
   '<h2>ألوان دافئة وألوان باردة</h2><p><b>الألوان الدافئة:</b> الأحمر والبرتقالي والأصفر. تذكّرنا بالشمس والنار.</p><p><b>الألوان الباردة:</b> الأزرق والأخضر والبنفسجي. تذكّرنا بالبحر والشجر.</p><p>الرسامون يستخدمون الألوان الدافئة للفرح والحركة، والباردة للهدوء.</p><p>جرّب أن ترسم بحرًا بالألوان الباردة، وشمسًا بالألوان الدافئة.</p>',
   '6-8', 1, 10, 3),
  ('knowledge', 'egypt-landmarks', 'معالم من مصر', 'الأهرامات وأبو الهول ونهر النيل',
   '<h2>معالم من مصر</h2><p><b>الأهرامات:</b> في الجيزة، بناها المصريون القدماء قبل آلاف السنين، وأكبرها هرم الملك خوفو.</p><p><b>أبو الهول:</b> تمثال ضخم بجسم أسد ورأس إنسان، يقف قرب الأهرامات.</p><p><b>نهر النيل:</b> يمر في مصر من الجنوب إلى الشمال ويصب في البحر المتوسط، وعلى ضفافه قامت الحضارة المصرية.</p>',
   '9-12', 2, 15, 2),
  ('knowledge', 'five-senses', 'الحواس الخمس', 'كيف نتعرّف على العالم من حولنا؟',
   '<h2>الحواس الخمس</h2><p>👀 <b>البصر</b> بالعينين: نرى الألوان والأشكال.</p><p>👂 <b>السمع</b> بالأذنين: نسمع الأصوات.</p><p>👃 <b>الشم</b> بالأنف: نشم رائحة الورد.</p><p>👅 <b>التذوق</b> باللسان: نعرف الحلو والمالح.</p><p>✋ <b>اللمس</b> بالجلد: نعرف الناعم والخشن والساخن والبارد.</p>',
   '6-8', 1, 10, 3)
) AS v(subject, slug, title, descr, content, age, diff, pts, ord) ON v.subject = s.slug
ON CONFLICT (subject_id, slug) DO NOTHING;

INSERT INTO quiz_questions (lesson_id, question_ar, options, correct_idx, explanation_ar, sort_order)
SELECT l.id, v.q, v.o::jsonb, v.c, v.e, v.s
FROM lessons l
JOIN (VALUES
  ('greetings-in-english', 'ما معنى Thank you؟', '["مرحبًا","شكرًا","مع السلامة"]', 1, 'Thank you تعني شكرًا.', 1),
  ('greetings-in-english', 'ماذا نقول في الصباح؟', '["Good morning","Goodbye","Thank you"]', 0, 'صباح الخير = Good morning.', 2),
  ('greetings-in-english', 'كيف نقول «مع السلامة»؟', '["Hello","Goodbye","Thank you"]', 1, 'مع السلامة = Goodbye.', 3),
  ('numbers-in-english', 'ما معنى Three؟', '["٢","٣","٥"]', 1, 'Three = ٣.', 1),
  ('numbers-in-english', 'كيف نقول ٥ بالإنجليزية؟', '["Four","Five","One"]', 1, '٥ = Five.', 2),
  ('numbers-in-english', 'ما العدد الذي يأتي بعد One؟', '["Two","Four","Three"]', 0, 'بعد One يأتي Two.', 3),
  ('odd-one-out', '🍎 🍌 🍇 ⚽ مَنِ الْمُخْتَلِفُ؟', '["🍎","🍇","⚽"]', 2, 'الْكُرَةُ لَيْسَتْ فَاكِهَةً.', 1),
  ('odd-one-out', '🐶 🐱 🐰 🚗 مَنِ الْمُخْتَلِفُ؟', '["🐱","🚗","🐰"]', 1, 'السَّيَّارَةُ لَيْسَتْ حَيَوَانًا.', 2),
  ('odd-one-out', '🔴 🔴 🔵 🔴 مَنِ الْمُخْتَلِفُ؟', '["🔴","🔵"]', 1, 'الْأَزْرَقُ مُخْتَلِفٌ عَنِ الْأَحْمَرِ.', 3),
  ('big-and-small', 'أَيُّهَا الْأَكْبَرُ؟', '["قِطَّةٌ 🐱","فِيلٌ 🐘","نَمْلَةٌ 🐜"]', 1, 'الْفِيلُ أَكْبَرُ مِنَ الْقِطَّةِ وَالنَّمْلَةِ.', 1),
  ('big-and-small', 'أَيُّهَا الْأَصْغَرُ؟', '["نَمْلَةٌ 🐜","حِصَانٌ 🐴","كَلْبٌ 🐶"]', 0, 'النَّمْلَةُ هِيَ الْأَصْغَرُ.', 2),
  ('big-and-small', 'مَا التَّرْتِيبُ مِنَ الصَّغِيرِ إِلَى الْكَبِيرِ؟', '["🐘 🐱 🐜","🐜 🐱 🐘","🐱 🐜 🐘"]', 1, 'النَّمْلَةُ ثُمَّ الْقِطَّةُ ثُمَّ الْفِيلُ.', 3),
  ('shapes-around-us', 'الشَّمْسُ تُشْبِهُ…', '["الدَّائِرَةَ","الْمُثَلَّثَ","الْمُرَبَّعَ"]', 0, 'الشَّمْسُ مُسْتَدِيرَةٌ مِثْلُ الدَّائِرَةِ.', 1),
  ('shapes-around-us', 'كَمْ ضِلْعًا لِلْمُثَلَّثِ؟', '["اثْنَانِ","ثَلَاثَةٌ","أَرْبَعَةٌ"]', 1, 'لِلْمُثَلَّثِ ثَلَاثَةُ أَضْلَاعٍ.', 2),
  ('shapes-around-us', 'أَيُّ شَكْلٍ لَهُ أَرْبَعَةُ أَضْلَاعٍ مُتَسَاوِيَةٍ؟', '["الدَّائِرَةُ","الْمُرَبَّعُ","الْمُثَلَّثُ"]', 1, 'لِلْمُرَبَّعِ أَرْبَعَةُ أَضْلَاعٍ مُتَسَاوِيَةٍ.', 3),
  ('warm-and-cool-colors', 'أي لون من الألوان الدافئة؟', '["الأزرق","البرتقالي","البنفسجي"]', 1, 'البرتقالي لون دافئ.', 1),
  ('warm-and-cool-colors', 'أي لون من الألوان الباردة؟', '["الأحمر","الأصفر","الأخضر"]', 2, 'الأخضر لون بارد.', 2),
  ('warm-and-cool-colors', 'لرسم بحر هادئ نستخدم غالبًا:', '["ألوانًا باردة","ألوانًا دافئة"]', 0, 'الأزرق والأخضر ألوان باردة هادئة.', 3),
  ('egypt-landmarks', 'أين تقع الأهرامات؟', '["الأقصر","الجيزة","أسوان"]', 1, 'الأهرامات في الجيزة.', 1),
  ('egypt-landmarks', 'تمثال بجسم أسد ورأس إنسان هو:', '["أبو الهول","الهرم الأكبر","تمثال الحرية"]', 0, 'أبو الهول بجسم أسد ورأس إنسان.', 2),
  ('egypt-landmarks', 'في أي بحر يصب نهر النيل؟', '["البحر الأحمر","البحر المتوسط","بحر العرب"]', 1, 'يصب النيل في البحر المتوسط.', 3),
  ('five-senses', 'بأي عضو نسمع؟', '["العين","الأذن","الأنف"]', 1, 'نسمع بالأذنين.', 1),
  ('five-senses', 'كم عدد الحواس؟', '["ثلاث","أربع","خمس"]', 2, 'البصر والسمع والشم والتذوق واللمس.', 2),
  ('five-senses', 'نعرف أن الطعام مالح بحاسة:', '["التذوق","السمع","البصر"]', 0, 'التذوق باللسان.', 3)
) AS v(slug, q, o, c, e, s) ON v.slug = l.slug
WHERE NOT EXISTS (SELECT 1 FROM quiz_questions qq WHERE qq.lesson_id = l.id);
